from itertools import combinations, product
from math import factorial
z={'Z1':0.,'Z2':1.,'Z3':1.}
players=tuple(z)
def value(s):
    # Admissible special case: independent zero-mean roots Z2,Z3,
    # Z1=Z2+Z3+epsilon1, and output=Z1.
    if 'Z1' in s:
        return z['Z1']
    return sum(z[k] for k in ['Z2','Z3'] if k in s)
phi=0.
for k in range(3):
    for s in combinations(['Z2','Z3'],k):
        phi+=factorial(k)*factorial(2-k)/factorial(3)*(value(set(s)|{'Z1'})-value(set(s)))
print('SCM interventional Shapley for Z1:',phi)
print('Appendix A.1 expression in this special case:',z['Z1'])
intercept=-1.82530524
w={'C':0.09042825,'H':1.56043942,'T':0.07410451,'V':1.27937188}
for h,v in product([0,1],repeat=2):
    scores=[intercept+w['H']*h+w['V']*v+w['C']*c+w['T']*t for c,t in product([0,1],repeat=2)]
    print('Simulation hard binary-head output:',{'H':h,'V':v,'score_range':(min(scores),max(scores)),'labels':sorted(set(int(s>=0) for s in scores))})
